        sql = "SELECT scene FROM players WHERE tag='{}';".format(player)
        res = self.db.exec(sql)

        if len(res) == 0 or res[0][0] == scene:

            map = {'rank':rank, 'total_ranked':len(ranks)}
            tag_rank_map[player] = map

    player_web.update_ranks(tag_rank_map)

